<?php
session_start();
require_once __DIR__.'/../includes/config.php';
if(!isset($conn)||!($conn instanceof mysqli))die('Database connection is not available.');
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function tableExists($c,$t){$t=$c->real_escape_string($t);$r=$c->query("SHOW TABLES LIKE '$t'");return $r&&$r->num_rows>0;}
function imgUrl($v){$v=trim((string)$v);if($v==='')return '';if(preg_match('/^(https?:\/\/|data:|\/)/i',$v))return $v;if(strpos($v,'assets/')===0)return '../'.$v;return '../assets/images/restaurants/'.basename($v);}
$admin=!empty($_SESSION['admin_logged_in']);
if(!$admin&&!empty($_SESSION['user_id'])&&tableExists($conn,'users')){$id=(int)$_SESSION['user_id'];$s=$conn->prepare("SELECT role,full_name,email FROM users WHERE id=? LIMIT 1");if($s){$s->bind_param('i',$id);$s->execute();$u=$s->get_result()->fetch_assoc();$s->close();if($u&&strtolower((string)($u['role']??''))==='admin'){$admin=true;$_SESSION['admin_logged_in']=true;$_SESSION['admin_name']=$u['full_name']??'Administrator';$_SESSION['admin_email']=$u['email']??'';}}}
if(!$admin){header('Location: ../admin-login.php');exit;}if(!tableExists($conn,'restaurant_users'))die("Database table 'restaurant_users' was not found.");
$msg='';$msgType='';
if($_SERVER['REQUEST_METHOD']==='POST'){$oid=(int)($_POST['restaurant_id']??0);$action=$_POST['action']??'';$allowed=['approve','reject','block','activate'];if($oid<=0||!in_array($action,$allowed,true)){$msg='Invalid restaurant action.';$msgType='error';}else{$status=($action==='approve'||$action==='activate')?'active':'blocked';$s=$conn->prepare("UPDATE restaurant_users SET status=? WHERE id=? LIMIT 1");if($s){$s->bind_param('si',$status,$oid);if($s->execute()){$msg=$status==='active'?'Restaurant approved successfully.':'Restaurant restricted successfully.';$msgType='success';}else{$msg='Unable to update restaurant status: '.$s->error;$msgType='error';}$s->close();}else{$msg='Database error: '.$conn->error;$msgType='error';}}}
$filter=$_GET['status']??'all';$filters=['all','pending','active','inactive','blocked'];if(!in_array($filter,$filters,true))$filter='all';$search=trim($_GET['search']??'');
$counts=['all'=>0,'pending'=>0,'active'=>0,'inactive'=>0,'blocked'=>0];$r=$conn->query("SELECT COUNT(*) total,SUM(status='pending') pending_count,SUM(status='active') active_count,SUM(status='inactive') inactive_count,SUM(status='blocked') blocked_count FROM restaurant_users");if($r&&($x=$r->fetch_assoc())){foreach(['all'=>'total','pending'=>'pending_count','active'=>'active_count','inactive'=>'inactive_count','blocked'=>'blocked_count'] as $k=>$v)$counts[$k]=(int)($x[$v]??0);}
$list=[];
if(tableExists($conn,'restaurants')&&tableExists($conn,'orders')){$sql="SELECT ru.id owner_id,ru.restaurant_name,ru.full_name,ru.email,ru.phone,ru.status,ru.created_at,r.id restaurant_id,r.image restaurant_image,COALESCE(m.order_count,0) monthly_orders,COALESCE(m.order_total,0) monthly_total FROM restaurant_users ru LEFT JOIN restaurants r ON r.name=ru.restaurant_name LEFT JOIN(SELECT restaurant_id,COUNT(*) order_count,COALESCE(SUM(total),0) order_total FROM orders WHERE created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01') AND order_status IN('delivered','completed') GROUP BY restaurant_id)m ON m.restaurant_id=r.id";$w=[];$types='';$p=[];if($filter!=='all'){$w[]='ru.status=?';$types.='s';$p[]=$filter;}if($search!==''){$w[]='(ru.restaurant_name LIKE ? OR ru.full_name LIKE ? OR ru.email LIKE ? OR ru.phone LIKE ?)';$types.='ssss';$q='%'.$search.'%';array_push($p,$q,$q,$q,$q);}if($w)$sql.=' WHERE '.implode(' AND ',$w);$sql.=' ORDER BY ru.created_at DESC';$s=$conn->prepare($sql);if($s){if($types)$s->bind_param($types,...$p);$s->execute();$res=$s->get_result();while($row=$res->fetch_assoc())$list[]=$row;$s->close();}}
else{$sql="SELECT id owner_id,restaurant_name,full_name,email,phone,status,created_at,0 restaurant_id,'' restaurant_image,0 monthly_orders,0 monthly_total FROM restaurant_users";$w=[];$types='';$p=[];if($filter!=='all'){$w[]='status=?';$types.='s';$p[]=$filter;}if($search!==''){$w[]='(restaurant_name LIKE ? OR full_name LIKE ? OR email LIKE ? OR phone LIKE ?)';$types.='ssss';$q='%'.$search.'%';array_push($p,$q,$q,$q,$q);}if($w)$sql.=' WHERE '.implode(' AND ',$w);$sql.=' ORDER BY created_at DESC';$s=$conn->prepare($sql);if($s){if($types)$s->bind_param($types,...$p);$s->execute();$res=$s->get_result();while($row=$res->fetch_assoc())$list[]=$row;$s->close();}}
?>
