rap;margin-bottom:13px}.tab{padding:8px 11px;border:1px solid #ead6df;border-radius:8px;color:#666;font-size:10px;font-weight:800}.tab.on{color:#fff;background:#ed0038;border-color:#ed0038}.search{display:flex;gap:8px}.search input{height:42px;flex:1;border:1px solid #ddd;border-radius:9px;padding:0 13px;font-size:12px}.search button{height:42px;border:0;border-radius:9px;padding:0 18px;color:#fff;background:#ed0038;font-size:12px;font-weight:800}.panel{background:#fff;border:1px solid #f0dce5;border-radius:17px;padding:18px}.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.panel-head h2{margin:0;font-size:16px}.panel-head span{font-size:10px;color:#999}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.card{border:1px solid #f0dce5;border-radius:15px;overflow:hidden;background:#fff}.head{display:flex;gap:13px;padding:15px;border-bottom:1px solid #f3e6eb}.pic{width:82px;height:82px;flex:0 0 82px;border-radius:13px;overflow:hidden;background:#fff0f5;color:#ef003c;display:flex;align-items:center;justify-content:center;font-size:25px}.pic img{width:100%;height:100%;object-fit:cover}.name{font-size:16px;font-weight:900}.rid{font-size:9px;color:#aaa;margin-top:4px}.owner{font-size:10px;margin-top:9px}.owner b{font-size:11px}.info{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:14px 15px}.label{display:block;color:#999;font-size:8px;text-transform:uppercase;font-weight:800;margin-bottom:4px}.value{font-size:10px;font-weight:700;word-break:break-word}.contact{line-height:1.8;color:#555}.badge{display:inline-flex;gap:5px;align-items:center;padding:5px 9px;border-radius:20px;font-size:8px;font-weight:900;text-transform:capitalize}.badge.pending{color:#996600;background:#fff4d6}.badge.active{color:#177245;background:#e7f8ed}.badge.inactive{color:#8a5a00;background:#fff0d4}.badge.blocked{color:#b42318;background:#fff0ee}.monthly{margin:0 15px 14px;padding:12px;border-radius:11px;background:#fff8fb;border:1px solid #f3e3e9;display:grid;grid-template-columns:1fr 1fr;gap:10px}.monthly b{display:block;font-size:17px}.monthly span{font-size:8px;color:#888;text-transform:uppercase;font-weight:800}.actions{padding:13px 15px;border-top:1px solid #f3e6eb;display:flex;gap:6px;flex-wrap:wrap}.btn{border:0;border-radius:8px;padding:8px 11px;font-size:9px;font-weight:800;cursor:pointer}.view{color:#df0038;background:#fff0f5}.approve{color:#177245;background:#e7f8ed}.restrict{color:#b42318;background:#fff0ee}.empty{text-align:center;padding:55px;color:#999}.empty i{font-size:35px;color:#ef003c;display:block;margin-bottom:10px}.modal{position:fixed;inset:0;background:#0008;display:none;align-items:center;justify-content:center;padding:20px;z-index:100}.modal.show{display:flex}.modal-card{background:#fff;width:100%;max-width:540px;max-height:90vh;overflow:auto;border-radius:17px}.modal-head{padding:17px 20px;border-bottom:1px solid #eee;display:flex;justify-content:space-between}.modal-head h3{margin:0;font-size:16px}.close{border:0;background:#fff0f5;color:#e03;border-radius:8px;width:32px;height:32px}.modal-body{padding:20px}.modal-img{width:100%;height:180px;object-fit:cover;border-radius:13px;background:#fff0f5;margin-bottom:12px}.row{display:grid;grid-template-columns:140px 1fr;gap:10px;padding:10px 0;border-bottom:1px solid #f4e8ed;font-size:10px}.row span{color:#999;font-weight:700}.row b{word-break:break-word}@media(max-width:1100px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:800px){.main{margin-left:70px;padding:12px}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.top{display:block}.date{display:inline-block;margin-top:10px}.search{flex-direction:column}.search button{width:100%}.info{grid-template-columns:1fr}.grid{grid-template-columns:1fr}}
</style></head><body><?php include __DIR__.'/admin-sidebar.php'; ?><main class="main">
<div class="top"><div><h1>Manage Restaurants</h1><p>Review restaurant owners, approvals, restrictions and monthly performance.</p></div><div class="date"><i class="fa-regular fa-calendar"></i> <?=h(date('d M Y'))?></div></div>
<?php if($msg):?><div class="msg <?=h($msgType==='success'?'ok':'err')?>"><i class="fa-solid <?=$msgType==='success'?'fa-circle-check':'fa-circle-exclamation'?>"></i> <?=h($msg)?></div><?php endif;?>
<section class="hero"><div><h2>Restaurant Management</h2><p>Image, restaurant name, ID, owner, contact, status, actions and this month's delivered orders.</p></div><i class="fa-solid fa-store"></i></section>
<section class="stats"><div class="stat"><i class="fa-solid fa-store"></i><b><?=$counts['all']?></b><span>Total Restaurants</span></div><div class="stat pending"><i class="fa-solid fa-clock"></i><b><?=$counts['pending']?></b><span>Pending Approval</span></div><div class="stat active"><i class="fa-solid fa-circle-check"></i><b><?=$counts['active']?></b><span>Active</span></div><div class="stat inactive"><i class="fa-solid fa-circle-pause"></i><b><?=$counts['inactive']?></b><span>Inactive</span></div><div class="stat blocked"><i class="fa-solid fa-ban"></i><b><?=$counts['blocked']?></b><span>Restricted</span></div></section>
<section class="tools"><div class="tabs"><?php foreach($filters as $f):?><a class="tab <?=$filter===$f?'on':''?>" href="manage-restaurants.php?status=<?=h($f)?>"><?=ucfirst($f==='blocked'?'restricted':$f)?> (<?=$counts[$f]?>)</a><?php endforeach;?></div><form class="search" method="GET"><input type="hidden" name="status" value="<?=h($filter)?>"><input name="search" value="<?=h($search)?>" placeholder="Search restaurant, owner, email or phone..."><button><i class="fa-solid fa-search"></i> Search</button></form></section>
<section class="panel"><div class="panel-head"><div><h2>Restaurant Accounts</h2><span><?=count($list)?> restaurant(s) shown</span></div><span><?=ucfirst($filter==='blocked'?'restricted':$filter)?> records</span></div>
<?php if($list):?><div class="grid"><?php foreach($list as $x):$st=strtolower(trim((string)($x['status']??'pending')));$im=imgUrl($x['restaurant_image']??'');$rid=(int)($x['restaurant_id']??0);if(!$rid)$rid=(int)$x['owner_id'];$orders=(int)$x['monthly_orders'];$total=(float)$x['monthly_total'];$data=['id'=>$rid,'name'=>$x['restaurant_name']??'Restaurant','owner'=>$x['full_name']??'Owner','email'=>$x['email']??'','phone'=>$x['phone']??'','status'=>$st,'image'=>$im,'orders'=>$orders,'total'=>$total];?>
<article class="card"><div class="head"><div class="pic"><?php if($im):?><img src="<?=h($im)?>" alt="<?=h($x['restaurant_name'])?>" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><i class="fa-solid fa-store" style="display:none"></i><?php else:?><i class="fa-solid fa-store"></i><?php endif;?></div><div><div class="name"><?=h($x['restaurant_name']??'Restaurant')?></div><div class="rid">ID #<?=$rid?></div><div class="owner">Owner: <b><?=h($x['full_name']??'Owner')?></b></div></div></div>
<div class="info"><div><span class="label">Contact Details</span><div class="value contact"><i class="fa-solid fa-envelope"></i> <?=h($x['email']??'N/A')?><br><i class="fa-solid fa-phone"></i> <?=h($x['phone']??'N/A')?></div></div><div><span class="label">Status</span><div class="value"><span class="badge <?=$st?>"><i class="fa-solid <?=$st==='active'?'fa-circle-check':($st==='blocked'?'fa-ban':($st==='pending'?'fa-clock':'fa-circle-pause'))?>"></i><?=h($st==='blocked'?'restricted':$st)?></span></div></div></div>
<div class="monthly"><div><b><?=number_format($orders)?></b><span>This Month Orders</span></div><div><b>Rs <?=number_format($total,0)?></b><span>This Month Total</span></div></div>
<div class="actions"><button class="btn view" type="button" onclick='viewRestaurant(<?=json_encode($data,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>)'><i class="fa-solid fa-eye"></i> View</button><?php if($st==='pending'):?><form method="POST"><input type="hidden" name="restaurant_id" value="<?=$x['owner_id']?>"><input type="hidden" name="action" value="approve"><button class="btn approve" onclick="return confirm('Approve this restaurant?')"><i class="fa-solid fa-check"></i> Approval</button></form><form method="POST"><input type="hidden" name="restaurant_id" value="<?=$x['owner_id']?>"><input type="hidden" name="action" value="reject"><button class="btn restrict" onclick="return confirm('Restrict this restaurant?')"><i class="fa-solid fa-ban"></i> Restrict</button></form><?php elseif($st==='active'):?><form method="POST"><input type="hidden" name="restaurant_id" value="<?=$x['owner_id']?>"><input type="hidden" name="action" value="block"><button class="btn restrict" onclick="return confirm('Restrict this restaurant?')"><i class="fa-solid fa-ban"></i> Restricted</button></form><?php else:?><form method="POST"><input type="hidden" name="restaurant_id" value="<?=$x['owner_id']?>"><input type="hidden" name="action" value="activate"><button class="btn approve" onclick="return confirm('Approve this restaurant?')"><i class="fa-solid fa-check"></i> Approval</button></form><?php endif;?></div></article>
<?php endforeach;?></div><?php else:?><div class="empty"><i class="fa-solid fa-store-slash"></i><b>No restaurants found</b></div><?php endif;?></section></main>
<div class="modal" id="modal" onclick="if(event.target===this)closeModal()"><div class="modal-card"><div class="modal-head"><h3>Restaurant Details</h3><button class="close" onclick="closeModal()"><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body" id="modalBody"></div></div></div>
<script>function e(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function row(a,b){return '<div class="row"><span>'+e(a)+'</span><b>'+e(b)+'</b></div>'}function viewRestaurant(d){let m=document.getElementById('modal'),b=document.getElementById('modalBody');let im=d.image?'<img class="modal-img" src="'+e(d.image)+'" alt="Restaurant image">':'<div class="modal-img" style="display:flex;align-items:center;justify-content:center;font-size:45px;color:#e03"><i class="fa-solid fa-store"></i></div>';b.innerHTML=im+row('Restaurant ID','#'+d.id)+row('Restaurant Name',d.name)+row('Owner Name',d.owner)+row('Email',d.email||'N/A')+row('Phone',d.phone||'N/A')+row('Status',d.status==='blocked'?'Restricted':d.status)+row('This Month Orders',Number(d.orders).toLocaleString())+row('This Month Total','Rs '+Number(d.total).toLocaleString());m.classList.add('show')}function closeModal(){document.getElementById('modal').classList.remove('show')}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});</script></body></html>
